+// Keyset pagination over rows sorted newest first by key(row). A key is a number or an array of
+// numbers and strings, compared left to right.
+function compareKeys(a, b) {
+  const x = [].concat(a);
+  const y = [].concat(b);
+  for (let i = 0; i < x.length; i++) {
+    if (x[i] < y[i]) return -1;
+    if (x[i] > y[i]) return 1;
+  }
+  return 0;
+}
+
+function keysetPage(rows, afterKey, limit, key) {
+  const rest = afterKey === null || afterKey === undefined ? rows : rows.filter((r) => compareKeys(key(r), afterKey) < 0);
+  const items = rest.slice(0, limit + 1);
+  const more = items.length > limit;
+  if (more) items.pop();
+  return { items, more };
+}
+
